<section class="workspace-card" id="forwarding-requests"><h2>Email forwarding requests</h2><p>Clients can request one forwarding address for studio review. Permission is separate from mailbox creation. This workflow saves requests and review messages only; it does not send a provider change or activate forwarding.</p>
<?php try{$forwardingReady=provider_forwarding_ready();$forwardingHistory=$forwardingReady?provider_forwarding_history(null,max(1,(int)($_GET['forwarding_page']??1))):[];$forwardingOptions=$forwardingReady?provider_forwarding_options():[];}
catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p></section>';return;}
if(!$forwardingReady): ?><form method="post"><?php admin_action('provider_inventory_forwarding_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');?><button class="btn gold">Enable forwarding request history</button></form>
<?php else: ?>
<h3>Domain request permission</h3><p class="hint">Requires a fresh complete hosting response and an explicit client domain assignment. Limits apply to local requests, not provider quotas. A changed permission makes older requests ineligible for further review; they can still be declined or cancelled.</p>
<?php if(!$forwardingOptions):?><p>No current domain assignments are available for new permission. Refresh hosting inventory and confirm the client domain links.</p><?php endif;?>
<div class="workspace-grid"><?php foreach($forwardingOptions as $option):$p=$option['permission'];$b=$option['resource']['binding'];$retry=is_string($_POST['link_id']??null)&&$_POST['link_id']===$b['link_id'];$field=static fn(string $key,string $fallback,int $max=64):string=>$retry&&is_string($_POST[$key]??null)?substr($_POST[$key],0,$max):$fallback; ?>
<article class="workspace-card" data-forwarding-permission><h4 style="overflow-wrap:anywhere"><?=esc($b['domain'])?></h4><?php if(!$option['current']):?><p class="notice">Historical assignment. You can disable permission here; enabling it requires a current approved domain observation.</p><?php endif;?><form method="post"><?php admin_action('provider_inventory_forwarding_permission');?><input type="hidden" name="link_id" value="<?=esc($b['link_id'])?>"><input type="hidden" name="permission_id" value="<?=esc($field('permission_id',$p['id']??''))?>"><input type="hidden" name="event_id" value="<?=esc($field('event_id',bin2hex(random_bytes(16))))?>"><input type="hidden" name="context" value="<?=esc($field('context',$option['context']))?>">
<label>Client requests<select name="enabled"><option value="0"<?=$field('enabled',$p&&$p['payload']['enabled']?'1':'0')==='0'?' selected':''?>>Disabled</option><option value="1"<?=$field('enabled',$p&&$p['payload']['enabled']?'1':'0')==='1'?' selected':''?>>Allow forwarding requests</option></select></label>
<label>Requests per 24 hours<input type="number" name="daily_limit" min="1" max="20" value="<?=esc($field('daily_limit',(string)($p['payload']['daily_limit']??5)))?>" required></label><label>Permission expires in hours<input type="number" name="hours" min="1" max="720" value="<?=esc($field('hours','24'))?>" required></label><label><input type="checkbox" name="permission_confirm" value="1"> I authorize this client to request forwarding review for this domain.</label><button class="btn gold">Save forwarding permission</button></form></article><?php endforeach;?></div>
<h3>Client requests</h3><?php if(!$forwardingHistory): ?><p>No requests on this page.</p><?php endif;?><?php foreach($forwardingHistory as $doc)provider_forwarding_render_history($doc,true);$page=max(1,min(10000,(int)($_GET['forwarding_page']??1))); ?>
<nav class="button-row" aria-label="Forwarding request pages"><?php if($page>1):?><a class="btn outline" href="<?=esc(admin_url('provider-settings',['section'=>'website','forwarding_page'=>$page-1]))?>#forwarding-requests">Newer requests</a><?php endif;?><?php if(count($forwardingHistory)===20&&$page<10000):?><a class="btn outline" href="<?=esc(admin_url('provider-settings',['section'=>'website','forwarding_page'=>$page+1]))?>#forwarding-requests">Older requests</a><?php endif;?></nav>
<?php endif;?></section>
